-- Hyprland settings and animation defaults.
-- The color file is generated by Wallust, so read it on each config load.
local home = os.getenv("HOME") or "/home/fadilix"
local colors_path = home .. "/.config/hypr/wallust/wallust-hyprland.conf"
local active_border = "rgb(E5D7C4)"
local colors_file = io.open(colors_path, "r")
if colors_file then
    for line in colors_file:lines() do
        local value = line:match("^%s*%$color15%s*=%s*(.-)%s*$")
        if value then
            active_border = value
            break
        end
    end
    colors_file:close()
end

hl.config({
    dwindle = {
        preserve_split = true,
        special_scale_factor = 0.8,
    },
    master = {
        new_status = "master",
        new_on_top = true,
        mfact = 0.5,
    },
    general = {
        gaps_in = 4,
        gaps_out = 4,
        border_size = 0,
        resize_on_border = true,
        col = { active_border = active_border },
        layout = "master",
    },
    decoration = {
        rounding = 10,
        active_opacity = 1.0,
        inactive_opacity = 0.9,
        fullscreen_opacity = 1.0,
        dim_inactive = false,
        dim_strength = 0.1,
        dim_special = 0.8,
        blur = {
            enabled = true,
            size = 6,
            passes = 2,
            ignore_opacity = true,
            new_optimizations = true,
            special = true,
        },
    },
    animations = { enabled = true },
    render = {
        -- Avoid display profile changes and HDR modesets when entering fullscreen.
        send_content_type = false,
        cm_auto_hdr = 0,
    },
    input = {
        kb_layout = "fr,us",
        kb_options = "grp:alt_shift_toggle, caps:shiftlock",
        kb_rules = "",
        repeat_rate = 50,
        repeat_delay = 300,
        numlock_by_default = false,
        left_handed = false,
        follow_mouse = true,
        float_switch_override_focus = false,
        touchpad = {
            disable_while_typing = true,
            natural_scroll = true,
            clickfinger_behavior = false,
            middle_button_emulation = true,
            tap_to_click = true,
            drag_lock = false,
        },
    },
    gestures = {
        workspace_swipe_distance = 400,
        workspace_swipe_invert = true,
        workspace_swipe_min_speed_to_force = 5,
        workspace_swipe_cancel_ratio = 0.5,
        workspace_swipe_create_new = true,
        workspace_swipe_forever = true,
    },
    misc = {
        disable_hyprland_logo = true,
        disable_splash_rendering = true,
        mouse_move_enables_dpms = true,
        enable_swallow = true,
        swallow_regex = "^(kitty)$",
        focus_on_activate = false,
        initial_workspace_tracking = 0,
        middle_click_paste = false,
    },
    binds = {
        workspace_back_and_forth = true,
        allow_workspace_cycles = true,
        pass_mouse_when_bound = false,
    },
    xwayland = { force_zero_scaling = true },
    -- hyprcursor ignored app-requested shapes (resize, text, pointer) with Bibata; XCursor works.
    cursor = { enable_hyprcursor = false },
    -- Debug logging wrote every input event to disk (59 MB per session).
    debug = { disable_logs = true },
})

-- Formerly general.gesture = 3, horizontal, workspace.
hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })

-- Animations and curves from the active UserSettings.conf.
local curves = {
    wind = { 0.05, 0.9, 0.1, 1.05 },
    winIn = { 0.1, 1.1, 0.1, 1.1 },
    winOut = { 0.3, -0.3, 0, 1 },
    liner = { 1, 1, 1, 1 },
    menu_decel = { 0.1, 1, 0, 1 },
}
for name, points in pairs(curves) do
    hl.curve(name, {
        type = "bezier",
        points = { { points[1], points[2] }, { points[3], points[4] } },
    })
end

local animations = {
    { "windows", 3, "wind", "slide" },
    { "windowsIn", 3, "winIn", "slide" },
    { "windowsOut", 3, "winOut", "slide" },
    { "windowsMove", 3, "wind", "slide" },
    { "border", 1, "liner" },
    { "borderangle", 30, "liner", "loop" },
    { "fade", 10, "default" },
    { "workspaces", 4, "menu_decel", "slide" },
}
for _, animation in ipairs(animations) do
    hl.animation({
        leaf = animation[1],
        enabled = true,
        speed = animation[2],
        bezier = animation[3],
        style = animation[4],
    })
end

-- The animation picker writes the selected Lua preset here.
local active_animations = (os.getenv("HOME") or "/home/fadilix") .. "/.config/hypr/lua/active_animations.lua"
local active_chunk = loadfile(active_animations)
if active_chunk then active_chunk() end
